// Presentation intent only. Callers must wait for durable save success before
// emitting this cue. No cue is generated by render, resume, import or new game.
export function committedAudioIntent(before, action, after) {
  if (!before?.state || !after?.state || before.runId !== after.runId || after.revision <= before.revision) return null;
  const a=before.state,b=after.state;
  if (action.type === 'finishBattle') return b.battles.length > a.battles.length && b.battles.at(-1)?.receipt.result.win ? 'victory' : null;
  if (action.type === 'setFormation') {
    const changed=b.roster.filter(u=>a.roster.find(x=>x.id===u.id)?.slot!==u.slot);
    if (!changed.length) return null;
    return changed.length===2 && changed.every(u=>u.slot!==null) ? 'swap' : 'place';
  }
  if (!['claimReward','serviceAction','awaken','eventChoice'].includes(action.type)) return null;
  const relicEvolution=b.relics.some(r=>{const old=a.relics.find(x=>x.id===r.id);return old&&(r.evolution||1)>(old.evolution||1);});
  const classGrowth=b.roster.some(u=>{const old=a.roster.find(x=>x.id===u.id);return old&&((u.classStage||0)>(old.classStage||0)||u.type!==old.type||u.secondClassId!==old.secondClassId);});
  // Existing shop purchases use purchase_success, including shop growth offers.
  const choice=a.pendingService?.choices?.find(c=>c.candidateId===action.candidateId);
  if(action.type==='serviceAction'&&choice?.kind==='buy'&&b.gold<a.gold)return 'purchase';
  if(relicEvolution||classGrowth)return 'evolve';
  if(action.type==='serviceAction'&&['research','train','awakening-training'].includes(choice?.kind)&&b.gold<a.gold)return 'purchase';
  if(b.relics.some(r=>!a.relics.some(x=>x.id===r.id)))return 'reward';
  // Recruiting a real new unit is a gain; skip/reroll/training-only are silent.
  if(['claimReward','eventChoice'].includes(action.type)&&b.roster.some(u=>!a.roster.some(x=>x.id===u.id)))return 'reward';
  return null;
}
